    #[test]
    fn each_holder_reads_back_and_meets_the_stray_key_as_measured() {
        let failed: Vec<String> = HOLDERS.iter().flat_map(|holder| holder()).collect();
        assert_eq!(failed, Vec::<String>::new());
    }

    fn holder7() -> Vec<String> {
        check(
            "collide2:C2N0:CA10_NN|CE11_NN nonstrict",
            &rows2(|m0: CA10NN, m1: CE11NN| Holder7Draft { m0, m1 }),
            &[
                ("Dot,Dot", 'E'),
                ("Dot,Rect", 'E'),
                ("Dot,Wrap", 'E'),
                ("Rect,Dot", 'E'),
                ("Rect,Rect", 'E'),
                ("Rect,Wrap", 'E'),
                ("Wrap,Dot", 'E'),
                ("Wrap,Rect", 'E'),
                ("Wrap,Wrap", 'E'),
            ],
        )
    }

